<script setup>
import { computed } from 'vue';
import { formatTime } from '../game/RunState.js';
const props = defineProps({
    status: String, campaign: Object, health: Number, armor: Number, weapon: Object,
    kills: Number, enemyCount: Number, sigils: Number, requiredSigils: Number,
    elapsed: Number, message: String, prompt: String, damageFlash: Number,
    hitFlash: Number, pickupFlash: Number, muted: Boolean,
    sensitivity: Number, hasStarted: Boolean,
});
const emit = defineEmits(['resume', 'restart', 'next', 'home', 'mute', 'sensitivity']);
const overlay = computed(() => ['ready', 'paused', 'dead', 'complete'].includes(props.status));
const finished = computed(() => props.status === 'complete' && !props.campaign?.nextLevelUrl);
const title = computed(() => props.status === 'dead' ? 'Claimed by the dark' : finished.value ? 'The curse is broken' : props.status === 'complete' ? 'The seal is broken' : props.hasStarted ? 'Between worlds' : 'The Ruined Marches');
const subtitle = computed(() => props.status === 'dead' ? 'The stones remember. Rise, and try again.' : finished.value ? 'The final gate stands open. Dawn returns to the Ashen Realms.' : props.status === 'complete' ? 'Another threshold crossed. The darkness retreats.' : `Recover the ${props.requiredSigils} sigils. Unseal the gate. Survive the descent.`);
const infiniteWeapon = computed(() => Number(props.weapon?.cost ?? 0) === 0);
</script>

<template>
    <div class="game-hud" :class="{ 'low-health': health <= 25 }">
        <div class="screen-vignette" />
        <div class="damage-veil" :style="{ opacity: damageFlash }" />
        <div class="pickup-veil" :style="{ opacity: pickupFlash }" />
        <div v-if="status === 'playing'" class="crosshair" :class="{ 'crosshair-hit': hitFlash > 0 }"><i /><i /><i /><i /><b /></div>
        <Transition name="notice"><div v-if="message && status === 'playing'" :key="message" class="game-notice" role="status">{{ message }}</div></Transition>
        <div v-if="prompt && status === 'playing'" class="interaction-prompt"><kbd>E</kbd> {{ prompt }}</div>
        <footer class="status-bar">
            <div class="vitals-block">
                <div class="vital health"><span class="vital-symbol">✚</span><div class="vital-content"><div class="vital-reading"><span>VITALITY</span><strong>{{ health }}<small>/100</small></strong></div><div class="meter"><i :style="{ width: `${health}%` }" /></div></div></div>
                <div class="armor-reading"><span>◇</span> {{ armor }} <small>ARMOR</small></div>
            </div>
            <div class="sigil-block">
                <div class="sigil-row"><span v-for="n in requiredSigils" :key="n" class="sigil-gem" :class="{ collected: n <= sigils }">◆</span></div>
                <p>{{ sigils === requiredSigils ? 'GATE UNSEALED' : `${sigils} / ${requiredSigils} SIGILS` }}</p>
            </div>
            <div class="weapon-block">
                <div class="weapon-reading"><span>{{ weapon?.name || 'Unknown relic' }}</span><strong>{{ infiniteWeapon ? '∞' : weapon?.mana ?? 0 }}<small>{{ infiniteWeapon ? 'AETHER' : 'MANA' }}</small></strong></div>
            </div>
        </footer>
    </div>
    <section v-if="overlay" class="game-overlay" :class="{ 'death-overlay': status === 'dead' }" aria-labelledby="overlay-title">
        <div class="overlay-panel">
            <div class="ornament" aria-hidden="true"><span />✦<span /></div>
            <p class="eyebrow">{{ status === 'dead' ? 'Your journey is not over' : status === 'complete' ? (finished ? 'Campaign complete' : `Chapter ${campaign?.levelNumber} complete`) : `Chapter ${campaign?.levelNumber || 1} / ${campaign?.totalLevels || 4}` }}</p>
            <h2 id="overlay-title">{{ title }}</h2>
            <p class="overlay-subtitle">{{ subtitle }}</p>
            <div v-if="status === 'complete' || status === 'dead'" class="results-row"><div><strong>{{ kills }} / {{ enemyCount }}</strong><span>ENEMIES SLAIN</span></div><div><strong>{{ sigils }} / {{ requiredSigils }}</strong><span>SIGILS RECOVERED</span></div><div><strong>{{ formatTime(elapsed) }}</strong><span>TIME IN THE DEEP</span></div></div>
            <div v-else class="controls-grid"><div><kbd>W A S D</kbd><span>Move</span></div><div><kbd>MOUSE</kbd><span>Look / fire</span></div><div><kbd>1 2 3 / SCROLL</kbd><span>Weapons</span></div><div><kbd>E</kbd><span>Enter portal</span></div><div><kbd>TAB</kbd><span>Dungeon map</span></div></div>
            <button v-if="status === 'ready' || status === 'paused'" class="game-button primary" @click="emit('resume')">{{ hasStarted ? 'Return to the dungeon' : 'Enter the dungeon' }} <span>→</span></button>
            <button v-else-if="status === 'dead'" class="game-button primary" @click="emit('restart')">Rise again <span>↻</span></button>
            <button v-else-if="!finished" class="game-button primary" @click="emit('next')">Descend to chapter {{ (campaign?.levelNumber || 1) + 1 }} <span>→</span></button>
            <button v-else class="game-button primary" @click="emit('home')">Return to the surface <span>→</span></button>
            <div v-if="status === 'ready' || status === 'paused'" class="game-settings"><button :aria-pressed="!muted" @click="emit('mute')">Sound <strong>{{ muted ? 'OFF' : 'ON' }}</strong></button><label>Mouse sensitivity <input aria-label="Mouse sensitivity" type="range" min="0.04" max="0.28" step="0.01" :value="sensitivity" @input="emit('sensitivity', Number($event.target.value))" /></label></div>
            <div class="overlay-links"><button v-if="hasStarted && status === 'paused'" @click="emit('restart')">Restart chapter</button><button v-if="!finished" @click="emit('home')">Main menu</button></div>
            <p v-if="status === 'ready' || status === 'paused'" class="checkpoint-note">Progress saves at the start of each chapter. Your wand never runs dry.</p>
        </div>
    </section>
</template>

