t{width:80px;height:3px;accent-color:#baa26e}.overlay-links{display:flex;gap:30px;justify-content:center;margin-top:27px}.overlay-links button{font:10px system-ui;color:#96a78e;cursor:pointer;letter-spacing:.08em;text-transform:uppercase;padding:5px}.overlay-links button:hover{color:#e4d7b3}.checkpoint-note{font:9px/1.7 system-ui;color:#596e60;margin:24px 0 0}.results-row{display:flex;justify-content:center;gap:40px;margin:35px 0}.results-row>div{display:flex;flex-direction:column;gap:10px}.results-row strong{font:27px Georgia;color:#d5c396}.results-row span{font:8px system-ui;letter-spacing:.08em;color:#8f9d8f}.death-overlay{background:radial-gradient(ellipse at 50% 35%,#2e1719ec,#090708f2 75%)}.death-overlay .overlay-panel h2{color:#e5b8a2}
